            do {
                let r = try TauAdicNAF.generate(key: key, a: a)
                checkEqual(TauAdicNAF.digitString(r.generated), gen, "A \(key) a=\(a)")
                checkEqual(TauAdicNAF.digitString(r.reduced), red, "B \(key) a=\(a)")
                checkEqual(TauAdicNAF.digitString(r.regenerated), regen, "C \(key) a=\(a)")
            } catch { check(false, "\(key) a=\(a): \(error)") }
        }
        // Beispiel der Dokumentation (Solinas): 9 = 1001b hat die τNAF {1,0,-1,0,0,1} (Programm: a = 0)
        checkEqual(TauAdicNAF.digitString(TauAdicNAF.tnaf(BigInt(9), BigInt(), mu: TauAdicNAF.mu(a: 0)).reversed()), "10-1001")
        // key-out.txt identisch zum Original
        let r = try TauAdicNAF.generate(key: "1001", a: 1)
        checkEqual(TauAdicNAF.keyOutText(r, source: "INPUT", milliseconds: 0),
                   "\nInput: 'a' = 1; binary key from 'INPUT'\nLength of input key: 4 bit\nBinary key from the most significant (MSB) to the least significant bit (LSB):\n1001\n\nOutput:\nResult of algorithm A:\nLength of the generated key: 6 bit\nGenerated 't-adic NAF' key (from MSB to LSB):\n-101001\nResult of algorithm B:\nLength of the reduced key: 4 bit\nReduced key (from MSB to LSB):\n10-11\nResult of algorithm C:\nLength of the regenerated key: 4 bit\nThe regenerated 't-adic NAF' key (from MSB to LSB):\n000-1\nTotal time for calculations: 0 msec\n-------------------------------------\n")
        // Fehlerfälle wie im Original
        for (text, failure) in [("000", TauAdicNAF.Failure.generatedWrongly), ("10a1", .notADigit(after: 2)),
                                ("1021", .notBinary(after: 2)), ("", .empty), ("10 01", .notADigit(after: 2))] {
            do { _ = try TauAdicNAF.generate(key: text, a: 0); check(false, "kein Fehler für \(text)") }
            catch { checkEqual(error as? TauAdicNAF.Failure, failure, "Fehler für '\(text)'") }
        }
        checkEqual((try? TauAdicNAF.generate(key: "1001\n", a: 0))?.generated.count, 6, "abschließender Zeilenumbruch")
        // Mathematische Kontrolle: Σ u_i τ^i = k in Z[τ] (τ² = μτ − 2) für 163-Bit-Schlüssel
        for a in [0, 1] {
            var g = SystemRandomNumberGenerator()
            let bits = "1" + String((0..<162).map { _ in Bool.random(using: &g) ? "1" : "0" })
            let mu = BigInt(TauAdicNAF.mu(a: a))
            let u = TauAdicNAF.tnaf(BigInt(BigUInt(bits, radix: 2)!), BigInt(), mu: mu.intValue!)
            var x = BigInt(), y = BigInt()   // x + yτ, Horner von oben
            for d in u.reversed() {           // (x + yτ)τ = xτ + y(μτ − 2) = −2y + (x + μy)τ
                (x, y) = (-BigInt(2) * y + BigInt(d), x + mu * y)
            }
            check(x == BigInt(BigUInt(bits, radix: 2)!) && y.isZero, "τNAF-Wert stimmt (a=\(a))")
            check(u.count <= 2 * 163 + 4, "τNAF-Länge ≈ 2n")
        }
    }
